class XorBasis:
    def __init__(self, bits=64):
        self.basis = []
        self.bits = bits

    def insert(self, x):
        for b in self.basis:
            if (x ^ b) < x:
                x = x ^ b
        if x > 0:
            self.basis.append(x)
            self.basis.sort(reverse=True)

    def can_represent(self, target):
        for b in self.basis:
            if (target ^ b) < target:
                target = target ^ b
        
        return target == 0

printable = [chr(i) for i in range(ord('!'), ord('~') + 1)]

